/**
 * The 18th Vidhan Sabha as it stands, generated from
 * `uttar_pradesh_mlas_2026.csv` in the repo root. One row per seat, AC 1 to
 * 403, in order.
 *
 * `office` and `officeRank` are read from the source's Notes column, which
 * records who holds what. Rank 1 is the Chief Minister, 2 the Deputy Chief
 * Minister and the Speaker, 3 a Cabinet Minister or the Leader of the
 * Opposition, 4 a Minister of State with independent charge, 5 a Minister of
 * State. 0 is a member with no office recorded, which includes notes in that
 * column about deaths, defections and party roles.
 *
 * ESTIMATES: `economyPerSeatEst` comes from a column the source marks GUESS,
 * and `popPerSeat` divides a district projection evenly across its seats,
 * which real seats never are. Both size a drawing; neither is printed as a
 * figure.
 */
export interface MlaRow {
  ac: number;
  seat: string;
  district: string;
  name: string;
  party: string;
  alliance: string;
  /** ISO date, or empty for a vacant seat. */
  joined: string;
  /** District population, 2026 projection. Not the seat's electorate. */
  districtPop: number;
  seatsInDistrict: number;
  /** District projection divided by its seats. An estimate. */
  popPerSeat: number;
  /** Rs crore per seat, from the source's GUESS column. An estimate. */
  economyPerSeatEst: number;
  /** District rating out of 10, from the source's GUESS column. An estimate. */
  ratingEst: number;
  /** The office held, as the source records it. Empty if none. */
  office: string;
  /** 1 highest, 5 lowest, 0 for no office. */
  officeRank: number;
}

