export const mlaByAc = (ac: number): MlaRow | undefined => MLAS_2026[ac - 1];

export const isVacant = (row: MlaRow): boolean =>
  row.party === 'Vacant' || row.name === '' || row.name.toLowerCase() === 'vacant';

